SELECT DISTINCT cs.canonical_smiles, m.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units FROM assays a JOIN activities act ON a.assay_id = act.assay_id JOIN molecule_dictionary m ON act.molregno = m.molregno JOIN compound_structures cs ON m.molregno = cs.molregno WHERE a.chembl_id = 'CHEMBL1614459' AND act.standard_relation = '=' AND act.standard_value IS NOT NULL ORDER BY cs.canonical_smiles, m.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units
